protocol Greeting {
    func message() -> String
}

struct FriendlyGreeting: Greeting {
    func message() -> String { "Hello from Swift!" }
}

func getGreeting() -> some Greeting {
    return FriendlyGreeting()
}

let g = getGreeting()
print(g.message())

protocol Animal {
    func sound() -> String
}

struct Dog: Animal {
    func sound() -> String { "Woof" }
}

struct Cat: Animal {
    func sound() -> String { "Meow" }
}

let animals: [any Animal] = [Dog(), Cat()]
let sounds = animals.map { $0.sound() }.joined(separator: ", ")
print(sounds)

protocol Speaker {
    func speak() -> String
}

struct Announcer: Speaker {
    func speak() -> String { "Welcome everyone!" }
}

func makeSpeaker() -> some Speaker {
    return Announcer()
}

let s1 = makeSpeaker()
let s2 = makeSpeaker()
print(type(of: s1) == type(of: s2))

protocol NamedEntity {
    var name: String { get }
}

struct UserProfile: NamedEntity {
    let name: String
}

func formatName(_ entity: some NamedEntity) -> String {
    return "Entity: \(entity.name)"
}

let profile = UserProfile(name: "Sam")
print(formatName(profile))

protocol Measurable {
    var measurement: Double { get }
}

struct Speed: Measurable {
    let measurement: Double
}

struct Weight: Measurable {
    let measurement: Double
}

func sumMeasurements(items: [any Measurable]) -> Double {
    var total = 0.0
    for item in items {
        total += item.measurement
    }
    return total
}

let data: [any Measurable] = [Speed(measurement: 55.5), Weight(measurement: 44.5)]
print(sumMeasurements(items: data))

protocol Counter {
    var value: Int { get }
}

struct StepCounter: Counter {
    let value: Int
}

func createCounter(steps: Int) -> some Counter {
    return StepCounter(value: steps)
}

let c = createCounter(steps: 500)
print("Steps: \(c.value)")

protocol GreeterProtocol {
    func greeting() -> String
}

struct FriendlyGreeter: GreeterProtocol {
    func greeting() -> String { "Hi there" }
}

func printMessage(_ item: some GreeterProtocol) {
    print(item.greeting())
}

let boxedGreeter: any GreeterProtocol = FriendlyGreeter()
printMessage(boxedGreeter)

protocol Describable {
    func describe() -> String
}

struct Card: Describable, Equatable {
    let suit: String
    func describe() -> String { suit }
}

func makeCard() -> some Describable & Equatable {
    return Card(suit: "Hearts")
}

let c1 = makeCard()
let c2 = makeCard()
print(c1 == c2)

